[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>GreenBean Coffee — Your Daily Coffee Ritual</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=Playfair+Display:wght@400;600;700&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green: #00824A;
      --green-dark: #006b3e;
      --forest: #32462F;
      --cream: #F3CEA1;
      --cream-light: #FDF6ED;
      --brown: #6B3A2A;
      --brown-light: #C9956C;
      --text: #1A1A1A;
      --text-muted: #5A5A5A;
      --border: #E8DDD0;
      --white: #FFFFFF;
      --radius: 1rem;
      --radius-sm: 0.5rem;
      --shadow: 0 2px 12px rgba(50,70,47,0.08);
      --shadow-md: 0 4px 24px rgba(50,70,47,0.12);
      --font-body: 'DM Sans', system-ui, sans-serif;
      --font-display: 'Playfair Display', Georgia, serif;
    }

    body { font-family: var(--font-body); color: var(--text); background: var(--white); line-height: 1.6; }

    /* ─── HEADER ─── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: var(--white);
      border-bottom: 1px solid var(--border);
      box-shadow: var(--shadow);
    }
    .header-inner {
      max-width: 1280px; margin: 0 auto;
      padding: 0 1.5rem;
      display: flex; align-items: center; justify-content: space-between;
      height: 72px;
    }
    .logo {
      display: flex; align-items: center; gap: 0.5rem;
      font-family: var(--font-display); font-size: 1.5rem; font-weight: 700;
      color: var(--green); text-decoration: none;
    }
    .logo-icon {
      width: 40px; height: 40px; background: var(--green);
      border-radius: 50%; display: flex; align-items: center; justify-content: center;
      color: white; font-size: 1.1rem;
    }
    .nav-links {
      display: flex; align-items: center; gap: 0.25rem; list-style: none;
    }
    .nav-links a {
      padding: 0.5rem 0.875rem; border-radius: var(--radius-sm);
      font-weight: 500; font-size: 0.9375rem; text-decoration: none; color: var(--text);
      transition: background 150ms, color 150ms;
    }
    .nav-links a:hover, .nav-links a.active { background: var(--cream-light); color: var(--green); }
    .nav-actions { display: flex; align-items: center; gap: 0.75rem; }
    .btn-ghost {
      padding: 0.5rem 1rem; border-radius: 2rem; border: 1.5px solid var(--green);
      font-weight: 600; font-size: 0.875rem; cursor: pointer; background: transparent;
      color: var(--green); text-decoration: none; transition: all 150ms;
    }
    .btn-ghost:hover { background: var(--green); color: white; }
    .btn-primary {
      padding: 0.5rem 1.25rem; border-radius: 2rem; border: none;
      background: var(--green); color: white; font-weight: 600; font-size: 0.875rem;
      cursor: pointer; text-decoration: none; transition: background 150ms, transform 100ms;
    }
    .btn-primary:hover { background: var(--green-dark); }
    .btn-primary:active { transform: scale(0.97); }
    .hamburger {
      display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 0.5rem;
      background: none; border: none;
    }
    .hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all 200ms; }

    /* ─── HERO ─── */
    .hero {
      position: relative; overflow: hidden;
      min-height: 560px; display: flex; align-items: center;
      background: linear-gradient(135deg, var(--forest) 0%, #1a2e1a 100%);
    }
    .hero-bg {
      position: absolute; inset: 0;
      background-image: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=1600&h=700&fit=crop&auto=format');
      background-size: cover; background-position: center;
      opacity: 0.35;
    }
    .hero-content {
      position: relative; z-index: 2;
      max-width: 1280px; margin: 0 auto; padding: 5rem 1.5rem;
      display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center;
    }
    .hero-text { color: white; }
    .hero-eyebrow {
      display: inline-block; background: var(--cream); color: var(--forest);
      font-size: 0.8125rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase;
      padding: 0.25rem 0.875rem; border-radius: 2rem; margin-bottom: 1.25rem;
    }
    .hero-title {
      font-family: var(--font-display); font-size: clamp(2.5rem, 5vw, 4rem);
      font-weight: 700; line-height: 1.15; margin-bottom: 1.5rem;
      color: white;
    }
    .hero-cta { display: flex; gap: 1rem; flex-wrap: wrap; }
    .btn-hero {
      padding: 0.875rem 2rem; border-radius: 2rem; font-weight: 700; font-size: 1rem;
      cursor: pointer; text-decoration: none; transition: all 150ms; display: inline-block;
    }
    .btn-hero-primary { background: var(--green); color: white; border: 2px solid var(--green); }
    .btn-hero-primary:hover { background: var(--green-dark); border-color: var(--green-dark); transform: translateY(-2px); }
    .btn-hero-outline { background: transparent; color: white; border: 2px solid rgba(255,255,255,0.6); }
    .btn-hero-outline:hover { background: rgba(255,255,255,0.1); transform: translateY(-2px); }
    .hero-card {
      background: rgba(255,255,255,0.12); backdrop-filter: blur(12px);
      border: 1px solid rgba(255,255,255,0.2); border-radius: var(--radius);
      padding: 2rem; color: white;
    }
    .hero-card img { width: 100%; border-radius: 0.75rem; margin-bottom: 1rem; object-fit: cover; height: 200px; }
    .hero-card h3 { font-family: var(--font-display); font-size: 1.375rem; margin-bottom: 0.5rem; }
    .hero-card p { opacity: 0.85; font-size: 0.9375rem; margin-bottom: 1rem; }

    /* ─── SECTIONS ─── */
    .section { padding: 5rem 1.5rem; }
    .section-inner { max-width: 1280px; margin: 0 auto; }
    .section-cream { background: var(--cream-light); }
    .section-green { background: var(--forest); color: white; }
    .section-brown { background: var(--cream); }

    .promo-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; align-items: center; }
    .promo-grid.reverse { direction: rtl; }
    .promo-grid.reverse > * { direction: ltr; }

    .promo-image {
      border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-md);
    }
    .promo-image img { width: 100%; height: 400px; object-fit: cover; display: block; }
    .promo-content {}
    .eyebrow {
      font-size: 0.8125rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase;
      color: var(--green); margin-bottom: 0.75rem; display: block;
    }
    .section-green .eyebrow { color: var(--cream); }
    .promo-title {
      font-family: var(--font-display); font-size: clamp(1.75rem, 3vw, 2.5rem);
      font-weight: 700; line-height: 1.2; margin-bottom: 1rem;
    }
    .promo-body { font-size: 1.0625rem; color: var(--text-muted); margin-bottom: 2rem; line-height: 1.7; }
    .section-green .promo-body { color: rgba(255,255,255,0.8); }
    .section-green .promo-title { color: white; }

    .btn-green {
      display: inline-block; padding: 0.75rem 1.75rem; border-radius: 2rem;
      background: var(--green); color: white; font-weight: 700; font-size: 0.9375rem;
      text-decoration: none; border: none; cursor: pointer; transition: all 150ms;
    }
    .btn-green:hover { background: var(--green-dark); transform: translateY(-1px); }
    .btn-green-outline {
      display: inline-block; padding: 0.75rem 1.75rem; border-radius: 2rem;
      background: transparent; color: white; font-weight: 700; font-size: 0.9375rem;
      text-decoration: none; border: 2px solid white; cursor: pointer; transition: all 150ms;
    }
    .btn-green-outline:hover { background: white; color: var(--forest); }
    .btn-cream {
      display: inline-block; padding: 0.75rem 1.75rem; border-radius: 2rem;
      background: var(--cream); color: var(--forest); font-weight: 700; font-size: 0.9375rem;
      text-decoration: none; border: none; cursor: pointer; transition: all 150ms;
    }
    .btn-cream:hover { background: #e8bc8a; transform: translateY(-1px); }

    /* AI Recommendation */
    .ai-section {
      background: linear-gradient(135deg, #f0faf5 0%, #e8f5ee 100%);
      border: 1px solid #c8e8d8;
    }
    .ai-inner {
      max-width: 1280px; margin: 0 auto; padding: 4rem 1.5rem;
      display: flex; align-items: center; gap: 3rem;
    }
    .ai-badge {
      flex-shrink: 0; width: 80px; height: 80px; background: var(--green);
      border-radius: 50%; display: flex; align-items: center; justify-content: center;
      font-size: 2rem;
    }
    .ai-content { flex: 1; }
    .ai-content h2 { font-family: var(--font-display); font-size: 1.75rem; margin-bottom: 0.75rem; color: var(--forest); }
    .ai-content p { color: var(--text-muted); font-size: 1.0625rem; margin-bottom: 1.5rem; }

    /* ─── SEASONAL HIGHLIGHTS ─── */
    .highlights-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; }
    .highlight-card {
      border-radius: var(--radius); overflow: hidden; position: relative;
      box-shadow: var(--shadow); transition: transform 200ms, box-shadow 200ms;
    }
    .highlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .highlight-card img { width: 100%; height: 320px; object-fit: cover; display: block; }
    .highlight-overlay {
      position: absolute; bottom: 0; left: 0; right: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, transparent 100%);
      padding: 2rem 1.5rem 1.5rem;
      color: white;
    }
    .highlight-overlay h3 { font-family: var(--font-display); font-size: 1.5rem; margin-bottom: 0.5rem; }
    .highlight-overlay p { font-size: 0.9375rem; opacity: 0.9; margin-bottom: 1rem; }

    /* ─── NONDAIRY ─── */
    .nondairy-banner {
      background: var(--cream); padding: 4rem 1.5rem;
      display: flex; align-items: center; justify-content: center; text-align: center;
    }
    .nondairy-inner { max-width: 600px; }
    .nondairy-inner h2 { font-family: var(--font-display); font-size: 2.25rem; margin-bottom: 1rem; color: var(--forest); }
    .nondairy-inner p { color: var(--text-muted); font-size: 1.0625rem; margin-bottom: 2rem; }

    /* ─── FOOTER ─── */
    .footer { background: var(--forest); color: rgba(255,255,255,0.85); padding: 4rem 1.5rem 2rem; }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-grid {
      display: grid; grid-template-columns: repeat(5, 1fr); gap: 2rem;
      border-bottom: 1px solid rgba(255,255,255,0.12); padding-bottom: 3rem; margin-bottom: 2rem;
    }
    .footer-col h4 {
      font-size: 0.8125rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em;
      color: white; margin-bottom: 1rem;
    }
    .footer-col ul { list-style: none; }
    .footer-col li { margin-bottom: 0.5rem; }
    .footer-col a { color: rgba(255,255,255,0.7); text-decoration: none; font-size: 0.9rem; transition: color 150ms; }
    .footer-col a:hover { color: var(--cream); }
    .footer-bottom {
      display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 1rem;
    }
    .footer-logo { font-family: var(--font-display); font-size: 1.25rem; color: white; font-weight: 700; }
    .footer-social { display: flex; gap: 0.75rem; }
    .footer-social a {
      width: 36px; height: 36px; border-radius: 50%; background: rgba(255,255,255,0.1);
      display: flex; align-items: center; justify-content: center; color: white;
      text-decoration: none; font-size: 0.875rem; transition: background 150ms;
    }
    .footer-social a:hover { background: var(--green); }
    .footer-copy { font-size: 0.8125rem; color: rgba(255,255,255,0.45); }
    .footer-accordion-btn {
      display: none; width: 100%; background: none; border: none; color: white;
      text-align: left; cursor: pointer; padding: 0.875rem 0; border-bottom: 1px solid rgba(255,255,255,0.1);
      font-family: var(--font-body); font-size: 0.8125rem; font-weight: 700;
      text-transform: uppercase; letter-spacing: 0.08em;
      display: none; align-items: center; justify-content: space-between;
    }
    .footer-accordion-btn .chevron { transition: transform 200ms; font-style: normal; }
    .footer-accordion-btn.open .chevron { transform: rotate(180deg); }
    .footer-accordion-content { display: block; }

    /* ─── COOKIE BANNER ─── */
    .cookie-banner {
      position: fixed; bottom: 0; left: 0; right: 0; z-index: 1000;
      background: var(--white); border-top: 1px solid var(--border);
      box-shadow: 0 -4px 24px rgba(0,0,0,0.1);
      padding: 1.25rem 1.5rem;
      display: flex; align-items: center; gap: 2rem; flex-wrap: wrap;
    }
    .cookie-text { flex: 1; min-width: 200px; }
    .cookie-text strong { display: block; font-weight: 700; margin-bottom: 0.25rem; }
    .cookie-text p { font-size: 0.875rem; color: var(--text-muted); }
    .cookie-actions { display: flex; gap: 0.75rem; flex-shrink: 0; }
    .btn-cookie-settings {
      padding: 0.625rem 1.25rem; border-radius: 2rem; border: 1.5px solid var(--border);
      background: transparent; font-weight: 600; font-size: 0.875rem; cursor: pointer; transition: all 150ms;
    }
    .btn-cookie-settings:hover { border-color: var(--green); color: var(--green); }
    .btn-cookie-agree {
      padding: 0.625rem 1.25rem; border-radius: 2rem; border: none;
      background: var(--green); color: white; font-weight: 600; font-size: 0.875rem;
      cursor: pointer; transition: background 150ms;
    }
    .btn-cookie-agree:hover { background: var(--green-dark); }

    /* ─── MOBILE ─── */
    @media (max-width: 768px) {
      .nav-links, .nav-actions { display: none; }
      .hamburger { display: flex; }
      .nav-links.open {
        display: flex; flex-direction: column; position: absolute;
        top: 72px; left: 0; right: 0;
        background: white; border-bottom: 1px solid var(--border);
        padding: 1rem; gap: 0.25rem; z-index: 99;
        box-shadow: var(--shadow-md);
      }
      .nav-links.open + .nav-actions {
        display: flex; flex-direction: column; padding: 0 1rem 1rem;
        position: absolute; top: auto; /* will be after nav-links */
        background: white;
      }
      .hero-content { grid-template-columns: 1fr; padding: 3rem 1.5rem; }
      .hero-card { display: none; }
      .promo-grid { grid-template-columns: 1fr; }
      .promo-grid.reverse { direction: ltr; }
      .highlights-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr; gap: 0; }
      .footer-accordion-btn { display: flex; }
      .footer-col h4 { display: none; }
      .footer-accordion-content { display: none; padding-bottom: 1rem; }
      .footer-accordion-content.open { display: block; }
      .ai-inner { flex-direction: column; text-align: center; }
    }
    @media (min-width: 769px) and (max-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }
  </style>
</head>
<body>

<!-- Cookie Banner -->
<div class="cookie-banner" id="cookieBanner">
