    .gc-cheer { background: linear-gradient(135deg, #27ae60 0%, #1e8449 100%); }
    .gc-any { background: linear-gradient(135deg, #00824A 0%, #1a6035 100%); }

    .carousel-btn {
      position: absolute; top: 50%; transform: translateY(-50%);
      width: 44px; height: 44px; border-radius: 50%;
      background: white; border: 1.5px solid var(--border);
      display: flex; align-items: center; justify-content: center;
      cursor: pointer; z-index: 5; font-size: 1.25rem; color: var(--forest);
      box-shadow: var(--shadow); transition: all 150ms;
    }
    .carousel-btn:hover { background: var(--green); color: white; border-color: var(--green); }
    .carousel-btn.prev { left: -22px; }
    .carousel-btn.next { right: -22px; }
    .carousel-btn:disabled { opacity: 0.35; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: white; color: var(--forest); border-color: var(--border); }

    /* CATEGORY CAROUSELS */
    .category-section { margin-bottom: 3.5rem; }
