    .btn-cream { display: inline-block; padding: 0.875rem 2rem; border-radius: 2rem; background: var(--cream); color: var(--forest); font-weight: 700; text-decoration: none; border: none; cursor: pointer; transition: all 150ms; font-size: 0.9375rem; }
    .btn-cream:hover { background: #e8bc8a; transform: translateY(-1px); }
    .biz-stats { display: flex; gap: 2rem; margin-bottom: 2rem; }
    .biz-stat { }
    .biz-stat-num { font-family: var(--font-display); font-size: 2rem; font-weight: 700; color: var(--cream); }
    .biz-stat-label { font-size: 0.875rem; opacity: 0.75; }

    /* EGIFT */
    .egift-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; align-items: center; }
    .egift-content h2 { font-family: var(--font-display); font-size: 2rem; color: var(--forest); margin-bottom: 1rem; }
    .egift-content p { color: var(--text-muted); font-size: 1.0625rem; margin-bottom: 1.5rem; line-height: 1.7; }
    .egift-features { list-style: none; margin-bottom: 2rem; }
    .egift-features li { padding: 0.5rem 0; border-bottom: 1px solid var(--border); font-size: 0.9375rem; color: var(--text-muted); display: flex; gap: 0.75rem; align-items: flex-start; }
    .egift-features li::before { content: '✓'; color: var(--green); font-weight: 700; flex-shrink: 0; }
    .egift-img { border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow-md); }
    .egift-img img { width: 100%; object-fit: cover; display: block; height: 320px; }

    /* FAQ */
    .faq-list { max-width: 800px; margin: 0 auto; }
    .faq-item { border: 1px solid var(--border); border-radius: var(--radius-sm); margin-bottom: 0.75rem; overflow: hidden; }
    .faq-btn { width: 100%; background: white; border: none; padding: 1.25rem 1.5rem; text-align: left; font-family: var(--font-body); font-size: 1rem; font-weight: 600; color: var(--text); cursor: pointer; display: flex; justify-content: space-between; align-items: center; transition: background 150ms; }
    .faq-btn:hover { background: var(--cream-light); }
    .faq-btn .faq-chevron { transition: transform 200ms; flex-shrink: 0; margin-left: 1rem; }
    .faq-btn.open .faq-chevron { transform: rotate(180deg); }
    .faq-answer { display: none; padding: 0 1.5rem 1.25rem; font-size: 0.9375rem; color: var(--text-muted); line-height: 1.7; }
    .faq-answer.open { display: block; }

    /* FOOTER */
    .footer { background: var(--forest); color: rgba(255,255,255,0.85); padding: 4rem 1.5rem 2rem; }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: repeat(5,1fr); gap: 2rem; border-bottom: 1px solid rgba(255,255,255,0.12); padding-bottom: 3rem; margin-bottom: 2rem; }
