    { name: "Westlake Center", address: "400 Pine St, Seattle, WA 98101", hours: "Open until 8:00 PM", open: true, features: ["Mobile ordering", "In-store seating", "Wi-Fi"], distance: "0.5 mi" },
    { name: "Capitol Hill Reserve", address: "1600 E Olive Way, Seattle, WA 98102", hours: "Open until 10:00 PM", open: true, features: ["Reserve bar", "In-store seating", "Wi-Fi", "Outdoor seating"], distance: "0.9 mi" },
    { name: "Belltown GreenBean", address: "2214 2nd Ave, Seattle, WA 98121", hours: "Open until 9:30 PM", open: true, features: ["Mobile ordering", "Curbside pickup"], distance: "1.1 mi" },
    { name: "SoDo Drive-Thru", address: "800 1st Ave S, Seattle, WA 98134", hours: "Open until 7:00 PM", open: true, features: ["Drive-thru", "Mobile ordering"], distance: "1.4 mi" },
    { name: "First Hill GreenBean", address: "325 9th Ave, Seattle, WA 98104", hours: "Closes at 6:00 PM", open: true, features: ["In-store seating", "Wi-Fi"], distance: "1.6 mi" },
    { name: "Madison Park Café", address: "4200 E Madison St, Seattle, WA 98112", hours: "Open until 8:30 PM", open: true, features: ["In-store seating", "Outdoor seating", "Wi-Fi"], distance: "2.3 mi" },
    { name: "Georgetown GreenBean", address: "5901 Airport Way S, Seattle, WA 98108", hours: "Closed — opens 6:00 AM", open: false, features: ["Drive-thru", "Mobile ordering"], distance: "3.1 mi" }
  ];

  let activeStore = 0;
  let orderType = 'pickup';

  function renderStores(list) {
    const container = document.getElementById('storeList');
    container.innerHTML = list.map(function(store, i) {
      return '<div class="store-card' + (i === activeStore ? ' active' : '') + '" onclick="selectStore(' + i + ')" tabindex="0" aria-label="' + store.name + '">' +
        '<div class="store-name">' + store.name + '</div>' +
        '<div class="store-address">📍 ' + store.address + '</div>' +
        '<div class="store-meta">' +
          '<span class="store-hours ' + (store.open ? 'open' : 'closed') + '">' + (store.open ? '● ' : '○ ') + store.hours + '</span>' +
          '<span class="store-distance">' + store.distance + '</span>' +
        '</div>' +
        '<div class="store-features">' + store.features.map(function(f) { return '<span class="store-feature-badge">' + f + '</span>'; }).join('') + '</div>' +
        '<div class="store-actions">' +
          '<a href="#" class="btn-store-action btn-store-order">Order ' + (orderType === 'delivery' ? 'delivery' : 'pickup') + '</a>' +
          '<a href="#" class="btn-store-action btn-store-dir">Get directions</a>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  function selectStore(index) {
    activeStore = index;
    renderStores(stores);
    // Scroll to active card
    const cards = document.querySelectorAll('.store-card');
    if (cards[index]) cards[index].scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    // Update map pins
    document.querySelectorAll('.map-pin').forEach(function(pin, i) {
      pin.classList.toggle('active-pin', i === index);
    });
  }

  function setOrderType(type) {
    orderType = type;
    document.getElementById('togglePickup').classList.toggle('active', type === 'pickup');
    document.getElementById('toggleDelivery').classList.toggle('active', type === 'delivery');
    renderStores(stores);
    document.getElementById('resultsHeading').textContent = type === 'delivery' ? 'Delivery available' : 'Nearby stores';
  }

  function toggleFilter() {
    const panel = document.getElementById('filterPanel');
    const btn = document.getElementById('filterBtn');
    const isVisible = panel.classList.toggle('visible');
    btn.classList.toggle('active', isVisible);
    btn.setAttribute('aria-expanded', isVisible);
  }

  function toggleChip(chip) {
    chip.classList.toggle('selected');
    updateFilterCount();
  }

  function updateFilterCount() {
    const selected = document.querySelectorAll('.filter-chip.selected').length;
    const countEl = document.getElementById('filterCount');
    if (selected > 0) {
      countEl.textContent = selected;
      countEl.style.display = 'inline-flex';
    } else {
      countEl.style.display = 'none';
    }
  }

  // Search suggestions
  const suggestionData = [
    { label: "Seattle, WA", icon: "🏙" },
    { label: "Pike Place Market, Seattle, WA", icon: "📍" },
    { label: "Capitol Hill, Seattle, WA", icon: "📍" },
    { label: "Bellevue, WA", icon: "🏙" },
    { label: "Redmond, WA", icon: "🏙" },
    { label: "98101 (Downtown Seattle)", icon: "📮" },
    { label: "98102 (Capitol Hill)", icon: "📮" },
    { label: "San Francisco, CA", icon: "🏙" },
    { label: "New York, NY", icon: "🏙" },
    { label: "Chicago, IL", icon: "🏙" }
  ];

  const searchInput = document.getElementById('searchInput');
  const suggestionsBox = document.getElementById('searchSuggestions');

  searchInput.addEventListener('input', function() {
    const val = searchInput.value.trim().toLowerCase();
    if (val.length < 2) { suggestionsBox.classList.remove('visible'); return; }
    const matches = suggestionData.filter(function(s) { return s.label.toLowerCase().includes(val); }).slice(0, 5);
    if (matches.length === 0) { suggestionsBox.classList.remove('visible'); return; }
    suggestionsBox.innerHTML = matches.map(function(s) {
      return '<div class="suggestion-item" role="option" tabindex="0" onclick="selectSuggestion(\'' + s.label.replace(/'/g, "\\'") + '\')">' +
        '<span class="suggestion-icon">' + s.icon + '</span>' + s.label + '</div>';
    }).join('');
    suggestionsBox.classList.add('visible');
  });

  function selectSuggestion(label) {
    searchInput.value = label;
    suggestionsBox.classList.remove('visible');
    document.getElementById('resultsCount').textContent = 'Showing stores near ' + label;
  }

  document.addEventListener('click', function(e) {
    if (!searchInput.contains(e.target) && !suggestionsBox.contains(e.target)) {
      suggestionsBox.classList.remove('visible');
    }
  });

  // Initialize
  renderStores(stores);
</script>
</body>
</html>
